    function officialModal() {
      let img = '', vf = null; const m = ui.modal(`<h3>Đăng bài chính thức</h3><p class="sub">Hiển thị trên bảng tin với tên “${esc(PL.brand())} Official”. Có thể kèm ảnh/video tải từ máy tính.</p><label class="lbl" for="o_t">Nội dung *</label><textarea class="field" id="o_t" rows="4" maxlength="1000"></textarea><label class="lbl" for="o_c">Chủ đề</label><select class="field" id="o_c">${['Thông báo', 'Hướng dẫn', 'Sự kiện', 'Mẹo tập luyện'].map(x => `<option>${x}</option>`).join('')}</select><div class="row" style="justify-content:flex-start;margin-top:12px"><button class="btn" id="o_i"><span class="material-symbols-outlined">image</span>Chọn ảnh</button><button class="btn" id="o_v"><span class="material-symbols-outlined">video_call</span>Chọn video</button></div><div id="o_p" class="sub"></div><div id="fe"></div><div class="row"><button class="btn" data-close>Hủy</button><button class="btn btn-pri" id="o_ok">Đăng</button></div>`);
      const pv = () => { $('#o_p', m).innerHTML = (img ? '🖼 Đã chọn ảnh. ' : '') + (vf ? '🎬 ' + esc(vf.name) + ' (' + bytes(vf.size) + ')' : ''); };
      $('#o_i', m).onclick = () => pickImage(1400, 'image/jpeg', d => { img = d; pv(); }); $('#o_v', m).onclick = () => pickVideo(f => { vf = f; pv(); });
      $('#o_ok', m).onclick = guard(async () => { const tx = $('#o_t', m).value.trim(); if (!tx && !img && !vf) { $('#fe', m).innerHTML = '<div class="err-txt">Hãy nhập nội dung hoặc chọn ảnh/video.</div>'; return; } const btn = $('#o_ok', m); btn.disabled = true; btn.textContent = 'Đang đăng…'; let key = '';
        if (vf) { key = 'official:' + PL.uid('v'); try { await MED.put(key, vf, 'official'); } catch (e) { btn.disabled = false; btn.textContent = 'Đăng'; throw new Error('Không thể lưu video: ' + (e.message || 'hết dung lượng trình duyệt')); } }
        PL.officialPost({ text: tx, topic: $('#o_c', m).value, img, videoId: key, vname: vf ? vf.name : '', vsize: vf ? vf.size : 0 }); m.close(); ui.toast('Đã đăng bài chính thức'); draw(); });
    }
    /* ---- Thêm tài khoản đăng nhập (admin tạo trực tiếp, không cần người dùng tự đăng ký) ---- */
    function genPw() {
      const lo = 'abcdefghjkmnpqrstuvwxyz', up = 'ABCDEFGHJKMNPQRSTUVWXYZ', nu = '23456789', all = lo + up + nu, buf = new Uint32Array(1);
      const rnd = k => { (window.crypto || window.msCrypto).getRandomValues(buf); return buf[0] % k; };
      const c = [up[rnd(up.length)], lo[rnd(lo.length)], nu[rnd(nu.length)]]; while (c.length < 12) c.push(all[rnd(all.length)]);
      for (let i = c.length - 1; i > 0; i--) { const j = rnd(i + 1); [c[i], c[j]] = [c[j], c[i]]; } return c.join('');
    }
    const ROLE_HELP = { user: 'Người dùng thường: dùng ứng dụng, đăng nhập ở tab “Thành viên”.', editor: 'Biên tập viên: chỉnh giao diện, bài tập, dinh dưỡng, sản phẩm. Đăng nhập ở tab “Quản trị”.', moderator: 'Kiểm duyệt viên: xử lý bài viết, bình luận, báo cáo. Đăng nhập ở tab “Quản trị”.', admin: 'Quản trị viên: toàn quyền, gồm tạo/xóa tài khoản và cấu hình hệ thống. Đăng nhập ở tab “Quản trị”.' };
    function copyText(t) { try { if (navigator.clipboard && navigator.clipboard.writeText) return navigator.clipboard.writeText(t).then(() => true, () => false); } catch (e) {} const ta = document.createElement('textarea'); ta.value = t; ta.style.cssText = 'position:fixed;opacity:0'; document.body.appendChild(ta); ta.select(); let ok = false; try { ok = document.execCommand('copy'); } catch (e) {} ta.remove(); return Promise.resolve(ok); }
    function createUserModal() {
      PL.need('users.manage');
      const actorAdmin = PL.role(ST.realUser || ST.user) === 'admin', roles = Object.keys(PL.ROLES).filter(r => actorAdmin || !ST.isStaffRole(r));
      const m = ui.modal(`<h3>Thêm tài khoản đăng nhập</h3><p class="sub">Tạo tài khoản ngay, không cần người dùng tự đăng ký (kể cả khi đang đóng đăng ký). Người dùng đăng nhập bằng email và mật khẩu tạm bên dưới.</p>` +
        `<label class="lbl" for="x_n">Họ tên *</label><input class="field" id="x_n" maxlength="60" autocomplete="off"><label class="lbl" for="x_e">Email đăng nhập *</label><input class="field" id="x_e" type="email" autocomplete="off">` +
        `<label class="lbl" for="x_p">Mật khẩu tạm * (≥ 8 ký tự, gồm chữ và số)</label><div class="row" style="justify-content:flex-start;flex-wrap:nowrap;gap:8px"><input class="field" id="x_p" type="text" autocomplete="off" spellcheck="false" value="${genPw()}"><button class="btn" type="button" id="x_gen" title="Tạo mật khẩu ngẫu nhiên" aria-label="Tạo mật khẩu ngẫu nhiên"><span class="material-symbols-outlined">autorenew</span></button></div>` +
        `<label class="lbl" for="x_r">Vai trò</label><select class="field" id="x_r">${roles.map(r => `<option value="${r}" ${r === 'user' ? 'selected' : ''}>${PL.ROLES[r]}</option>`).join('')}</select><p class="sub" id="x_help" style="margin:6px 0 0">${ROLE_HELP.user}</p><div id="fe"></div><div class="row"><button class="btn" data-close>Hủy</button><button class="btn btn-pri" id="x_ok">Tạo tài khoản</button></div>`);
      $('#x_gen', m).onclick = () => { $('#x_p', m).value = genPw(); };
      $('#x_r', m).onchange = () => { $('#x_help', m).textContent = ROLE_HELP[$('#x_r', m).value] || ''; };
      $('#x_ok', m).onclick = guard(() => {
        PL.need('users.manage'); const n = $('#x_n', m).value.trim(), e = $('#x_e', m).value.trim().toLowerCase(), pw = $('#x_p', m).value, r = $('#x_r', m).value, er = $('#fe', m), bad = t => { er.innerHTML = '<div class="err-txt">' + t + '</div>'; };
        if (n.length < 2) return bad('Họ tên cần ít nhất 2 ký tự.'); if (!ST.validEmail(e)) return bad('Email chưa đúng định dạng.'); if (!ST.strongPw(pw)) return bad('Mật khẩu cần ≥ 8 ký tự, gồm chữ và số.');
        if (ST.users().some(u => u.email === e)) return bad('Email này đã tồn tại.');
        if (ST.isStaffRole(r) && !actorAdmin) return bad('Chỉ quản trị viên mới được tạo tài khoản quản trị.');
        const btn = $('#x_ok', m); btn.disabled = true;
        return PL.createUserOnServer({ name: n, email: e, password: pw, role: r }).then(res => {
          if (!res.ok) { btn.disabled = false; return bad(esc(res.message || 'Không tạo được tài khoản.')); }
          m.close();
          const url = new URL('index.html' + (ST.isStaffRole(r) ? '?mode=admin' : ''), location.href).href, info = 'Tài khoản ' + (PL.brand() || 'DISCI') + '\nEmail: ' + e + '\nMật khẩu tạm: ' + pw + '\nĐăng nhập tại: ' + url + '\n(Vui lòng đổi mật khẩu sau khi đăng nhập)';
          const d = ui.modal(`<h3>Đã tạo tài khoản</h3><p class="sub">Gửi thông tin này cho người dùng. Mật khẩu chỉ hiển thị một lần – sau này chỉ có thể đặt lại.</p><div class="card-flat" style="line-height:1.9"><div><span class="sub">Họ tên:</span> <b>${esc(n)}</b> · ${esc(PL.ROLES[r])}</div><div><span class="sub">Email:</span> <b>${esc(e)}</b></div><div><span class="sub">Mật khẩu tạm:</span> <b style="font-size:20px;letter-spacing:.02em">${esc(pw)}</b></div><div><span class="sub">Trang đăng nhập:</span> <b>${esc(url)}</b></div></div><div class="row"><button class="btn" id="x_cp"><span class="material-symbols-outlined">content_copy</span>Sao chép thông tin</button><button class="btn" id="x_more"><span class="material-symbols-outlined">person_add</span>Thêm tài khoản khác</button><button class="btn btn-pri" data-close>Xong</button></div>`);
          $('#x_cp', d).onclick = () => copyText(info).then(ok => ui.toast(ok ? 'Đã sao chép thông tin đăng nhập' : 'Không sao chép được – hãy chép thủ công', ok ? undefined : 'err'));
          $('#x_more', d).onclick = () => { d.close(); createUserModal(); }; draw();
        });
      });
    }

